module.exports = {
  indexHtml: "<!DOCTYPE html>\r\n<html lang=\"en\">\r\n<head>\r\n  <meta charset=\"UTF-8\">\r\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n  <title>AWS Student Builder Community Day @ Rungta University</title>\r\n  \r\n  <!-- Modern Clean Typography -->\r\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\r\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\r\n  <link href=\"https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@400;500;700&family=Plus+Jakarta+Sans:wght@300;400;500;600;700;800;900&display=swap\" rel=\"stylesheet\">\r\n  \r\n  <style>\r\n    :root {\r\n      --bg-dark: #030712;\r\n      --card-bg: rgba(15, 23, 42, 0.75);\r\n      --card-hover: rgba(30, 41, 59, 0.9);\r\n      --border-color: rgba(56, 189, 248, 0.2);\r\n      --border-glow: rgba(56, 189, 248, 0.6);\r\n      --aws-orange: #ff9900;\r\n      --aws-blue: #38bdf8;\r\n      --text-main: #ffffff;\r\n      --text-muted: #94a3b8;\r\n\r\n      /* Screenshot Registration Form Blueprint Styles */\r\n      --blueprint-bg: #0a101d;\r\n      --blueprint-container: #111827;\r\n      --blueprint-input: #0f172a;\r\n      --blueprint-border: #1e293b;\r\n      --blueprint-btn: #38bdf8;\r\n    }\r\n\r\n    * {\r\n      box-sizing: border-box;\r\n      margin: 0;\r\n      padding: 0;\r\n      font-family: 'Plus Jakarta Sans', system-ui, -apple-system, sans-serif;\r\n      -webkit-tap-highlight-color: transparent;\r\n    }\r\n\r\n    body {\r\n      background-color: var(--bg-dark);\r\n      color: var(--text-main);\r\n      min-height: 100vh;\r\n      display: flex;\r\n      flex-direction: column;\r\n      overflow-x: hidden;\r\n      position: relative;\r\n    }\r\n\r\n    /* Ambient Tech Blueprint Grid Overlay */\r\n    .bg-grid {\r\n      position: fixed;\r\n      inset: 0;\r\n      background-image: \r\n        linear-gradient(to right, rgba(255, 255, 255, 0.03) 1px, transparent 1px),\r\n        linear-gradient(to bottom, rgba(255, 255, 255, 0.03) 1px, transparent 1px);\r\n      background-size: 40px 40px;\r\n      z-index: -1;\r\n      pointer-events: none;\r\n    }\r\n\r\n    /* Glowing Ambient Background Animation */\r\n    .glow-aura {\r\n      position: fixed;\r\n      top: -10%;\r\n      left: 30%;\r\n      width: 500px;\r\n      height: 500px;\r\n      background: radial-gradient(circle, rgba(56, 189, 248, 0.15) 0%, rgba(3, 105, 161, 0.05) 50%, transparent 70%);\r\n      filter: blur(80px);\r\n      z-index: -1;\r\n      pointer-events: none;\r\n      animation: floatGlow 12s ease-in-out infinite alternate;\r\n    }\r\n\r\n    /* Header Navigation */\r\n    header {\r\n      display: flex;\r\n      justify-content: space-between;\r\n      align-items: center;\r\n      padding: 1.2rem 2rem;\r\n      background: rgba(3, 7, 18, 0.85);\r\n      border-bottom: 1px solid var(--border-color);\r\n      position: sticky;\r\n      top: 0;\r\n      z-index: 100;\r\n      backdrop-filter: blur(12px);\r\n    }\r\n\r\n    .logo {\r\n      font-weight: 800;\r\n      font-size: 1.15rem;\r\n      display: flex;\r\n      align-items: center;\r\n      gap: 0.6rem;\r\n    }\r\n\r\n    .logo-badge {\r\n      background: linear-gradient(135deg, var(--aws-orange), #ff5500);\r\n      color: #000;\r\n      font-size: 0.72rem;\r\n      font-weight: 800;\r\n      padding: 0.25rem 0.6rem;\r\n      border-radius: 6px;\r\n      text-transform: uppercase;\r\n    }\r\n\r\n    .logo-text span {\r\n      color: var(--aws-blue);\r\n    }\r\n\r\n    /* Hero Section */\r\n    main.hero {\r\n      flex: 1;\r\n      display: flex;\r\n      flex-direction: column;\r\n      align-items: center;\r\n      justify-content: center;\r\n      padding: 4.5rem 1.5rem 3.5rem;\r\n      max-width: 1000px;\r\n      margin: 0 auto;\r\n      width: 100%;\r\n      text-align: center;\r\n    }\r\n\r\n    .status-badge {\r\n      display: inline-flex;\r\n      align-items: center;\r\n      gap: 0.6rem;\r\n      background: rgba(15, 23, 42, 0.9);\r\n      border: 1px solid var(--border-glow);\r\n      padding: 0.45rem 1.2rem;\r\n      border-radius: 99px;\r\n      font-size: 0.82rem;\r\n      font-weight: 700;\r\n      color: var(--aws-blue);\r\n      margin-bottom: 1.8rem;\r\n    }\r\n\r\n    .pulse-dot {\r\n      width: 8px;\r\n      height: 8px;\r\n      background-color: var(--aws-blue);\r\n      border-radius: 50%;\r\n      box-shadow: 0 0 8px var(--aws-blue);\r\n      animation: pulse 2s infinite;\r\n    }\r\n\r\n    h1 {\r\n      font-size: clamp(2.2rem, 5vw, 3.8rem);\r\n      font-weight: 900;\r\n      line-height: 1.15;\r\n      margin-bottom: 1.2rem;\r\n      color: #ffffff;\r\n    }\r\n\r\n    h1 .highlight {\r\n      background: linear-gradient(135deg, #38bdf8 0%, #818cf8 50%, #c084fc 100%);\r\n      -webkit-background-clip: text;\r\n      -webkit-text-fill-color: transparent;\r\n    }\r\n\r\n    p.subtitle {\r\n      color: var(--text-muted);\r\n      font-size: clamp(1rem, 2vw, 1.2rem);\r\n      max-width: 620px;\r\n      margin-bottom: 2.5rem;\r\n      line-height: 1.6;\r\n    }\r\n\r\n    /* Primary Action Trigger Button */\r\n    .btn-primary {\r\n      background: linear-gradient(135deg, #0284c7 0%, #0369a1 50%, #6366f1 100%);\r\n      color: #fff;\r\n      border: 1px solid rgba(255, 255, 255, 0.3);\r\n      padding: 1rem 2.5rem;\r\n      font-size: 1rem;\r\n      font-weight: 800;\r\n      border-radius: 12px;\r\n      cursor: pointer;\r\n      display: inline-flex;\r\n      align-items: center;\r\n      gap: 0.6rem;\r\n      box-shadow: 0 0 25px rgba(2, 132, 199, 0.5);\r\n      transition: all 0.25s ease;\r\n    }\r\n\r\n    .btn-primary:hover {\r\n      transform: translateY(-2px);\r\n      box-shadow: 0 0 35px rgba(56, 189, 248, 0.7);\r\n    }\r\n\r\n    /* Bento Features Grid */\r\n    .bento-grid {\r\n      display: grid;\r\n      grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));\r\n      gap: 1.2rem;\r\n      width: 100%;\r\n      margin-top: 3.5rem;\r\n    }\r\n\r\n    .bento-card {\r\n      background: var(--card-bg);\r\n      border: 1px solid var(--border-color);\r\n      padding: 1.8rem;\r\n      border-radius: 16px;\r\n      text-align: left;\r\n      cursor: pointer;\r\n      transition: all 0.25s ease;\r\n    }\r\n\r\n    .bento-card:hover {\r\n      background: var(--card-hover);\r\n      border-color: var(--border-glow);\r\n      transform: translateY(-4px);\r\n    }\r\n\r\n    .card-icon {\r\n      font-size: 1.4rem;\r\n      margin-bottom: 1rem;\r\n    }\r\n\r\n    .bento-card h3 {\r\n      font-size: 1.1rem;\r\n      font-weight: 800;\r\n      margin-bottom: 0.4rem;\r\n      color: var(--text-main);\r\n      display: flex;\r\n      justify-content: space-between;\r\n    }\r\n\r\n    .bento-card p {\r\n      color: var(--text-muted);\r\n      font-size: 0.9rem;\r\n      line-height: 1.4;\r\n    }\r\n\r\n    /* Modal Overlay */\r\n    .modal-overlay {\r\n      display: none;\r\n      position: fixed;\r\n      inset: 0;\r\n      background: rgba(3, 7, 18, 0.88);\r\n      z-index: 1000;\r\n      justify-content: center;\r\n      align-items: center;\r\n      padding: 1.2rem;\r\n      backdrop-filter: blur(8px);\r\n    }\r\n\r\n    .modal-overlay.active {\r\n      display: flex !important;\r\n    }\r\n\r\n    /* REGISTRATION MODAL -> EXACT SCREENSHOT THEME */\r\n    .blueprint-modal {\r\n      background: var(--blueprint-container);\r\n      border: 1px solid var(--blueprint-border);\r\n      padding: 2rem;\r\n      border-radius: 12px;\r\n      width: 100%;\r\n      max-width: 500px;\r\n      max-height: 90vh;\r\n      overflow-y: auto;\r\n      position: relative;\r\n      box-shadow: 0 20px 40px rgba(0, 0, 0, 0.8);\r\n      animation: modalFadeIn 0.25s cubic-bezier(0.16, 1, 0.3, 1);\r\n    }\r\n\r\n    .close-modal {\r\n      position: absolute;\r\n      top: 1rem;\r\n      right: 1.2rem;\r\n      background: transparent;\r\n      border: none;\r\n      color: #94a3b8;\r\n      font-size: 1.8rem;\r\n      cursor: pointer;\r\n    }\r\n\r\n    .close-modal:hover {\r\n      color: #ffffff;\r\n    }\r\n\r\n    .step-header-img {\r\n      display: flex;\r\n      align-items: flex-start;\r\n      gap: 0.8rem;\r\n      margin-bottom: 0.8rem;\r\n    }\r\n\r\n    .step-icon-img {\r\n      color: var(--blueprint-btn);\r\n      font-size: 1.3rem;\r\n      margin-top: 0.1rem;\r\n    }\r\n\r\n    .blueprint-modal h2 {\r\n      font-family: 'JetBrains Mono', monospace;\r\n      font-size: 1.4rem;\r\n      font-weight: 700;\r\n      color: #ffffff;\r\n    }\r\n\r\n    .blueprint-modal p.desc {\r\n      color: #94a3b8;\r\n      font-size: 0.88rem;\r\n      margin-bottom: 1.5rem;\r\n      line-height: 1.4;\r\n    }\r\n\r\n    /* Form Fields Matching Screenshot */\r\n    .bp-group {\r\n      margin-bottom: 1.2rem;\r\n      text-align: left;\r\n    }\r\n\r\n    .bp-row {\r\n      display: flex;\r\n      gap: 0.8rem;\r\n    }\r\n\r\n    .bp-row .bp-group {\r\n      flex: 1;\r\n    }\r\n\r\n    .bp-group label {\r\n      display: block;\r\n      margin-bottom: 0.4rem;\r\n      font-family: 'JetBrains Mono', monospace;\r\n      font-size: 0.85rem;\r\n      color: #ffffff;\r\n    }\r\n\r\n    .bp-group label span.req {\r\n      color: var(--blueprint-btn);\r\n    }\r\n\r\n    .bp-group input, .bp-group select {\r\n      width: 100%;\r\n      padding: 0.85rem 0.9rem;\r\n      background: var(--blueprint-input);\r\n      border: 1px solid var(--blueprint-border);\r\n      color: #ffffff;\r\n      border-radius: 6px;\r\n      outline: none;\r\n      font-size: 0.9rem;\r\n      transition: border-color 0.2s ease;\r\n    }\r\n\r\n    .bp-group input:focus, .bp-group select:focus {\r\n      border-color: var(--blueprint-btn);\r\n    }\r\n\r\n    .bp-btn-action {\r\n      background: var(--blueprint-btn);\r\n      color: #000;\r\n      border: none;\r\n      padding: 0.9rem;\r\n      font-family: 'JetBrains Mono', monospace;\r\n      font-size: 0.9rem;\r\n      font-weight: 700;\r\n      border-radius: 6px;\r\n      cursor: pointer;\r\n      width: 100%;\r\n      text-transform: uppercase;\r\n      letter-spacing: 0.5px;\r\n      transition: background 0.2s ease;\r\n    }\r\n\r\n    .bp-btn-action:hover {\r\n      background: #7dd3fc;\r\n    }\r\n\r\n    /* Event Highlights Card */\r\n    .highlights-modal-card {\r\n      background: #0f172a;\r\n      border: 1px solid var(--border-glow);\r\n      padding: 2rem;\r\n      border-radius: 16px;\r\n      width: 100%;\r\n      max-width: 480px;\r\n      position: relative;\r\n    }\r\n\r\n    .highlights-list {\r\n      list-style: none;\r\n      text-align: left;\r\n      margin: 1.2rem 0;\r\n    }\r\n\r\n    .highlights-list li {\r\n      padding: 0.8rem 0;\r\n      border-bottom: 1px solid var(--border-color);\r\n      color: var(--text-muted);\r\n      font-size: 0.9rem;\r\n    }\r\n\r\n    .highlights-list li strong {\r\n      color: var(--aws-blue);\r\n    }\r\n\r\n    .success-box {\r\n      display: none;\r\n      text-align: center;\r\n      padding: 1.5rem 0;\r\n    }\r\n\r\n    @keyframes pulse {\r\n      0%, 100% { opacity: 1; }\r\n      50% { opacity: 0.3; }\r\n    }\r\n\r\n    @keyframes floatGlow {\r\n      0% { transform: translate(0, 0); }\r\n      100% { transform: translate(40px, 40px); }\r\n    }\r\n\r\n    @keyframes modalFadeIn {\r\n      from { opacity: 0; transform: scale(0.95); }\r\n      to { opacity: 1; transform: scale(1); }\r\n    }\r\n\r\n    .admin-link-btn {\r\n      background: rgba(15, 23, 42, 0.85);\r\n      border: 1px solid var(--border-glow);\r\n      color: var(--aws-blue);\r\n      text-decoration: none;\r\n      font-size: 0.82rem;\r\n      font-weight: 700;\r\n      padding: 0.45rem 0.95rem;\r\n      border-radius: 8px;\r\n      transition: all 0.2s ease;\r\n      display: inline-flex;\r\n      align-items: center;\r\n      gap: 0.4rem;\r\n    }\r\n    .admin-link-btn:hover {\r\n      background: rgba(56, 189, 248, 0.15);\r\n      box-shadow: 0 0 15px rgba(56, 189, 248, 0.3);\r\n      color: #fff;\r\n    }\r\n\r\n    /* Pass Card and WhatsApp elements */\r\n    .pass-container {\r\n      display: none;\r\n      text-align: left;\r\n      animation: modalFadeIn 0.3s ease;\r\n    }\r\n    .pass-card-box {\r\n      background: #090e1a;\r\n      border: 1px dashed var(--aws-blue);\r\n      border-radius: 10px;\r\n      padding: 1.2rem;\r\n      margin: 1.2rem 0;\r\n      position: relative;\r\n    }\r\n    .pass-badge {\r\n      display: inline-block;\r\n      background: rgba(56, 189, 248, 0.15);\r\n      border: 1px solid var(--aws-blue);\r\n      color: var(--aws-blue);\r\n      font-family: 'JetBrains Mono', monospace;\r\n      font-weight: 800;\r\n      font-size: 0.95rem;\r\n      padding: 0.3rem 0.7rem;\r\n      border-radius: 6px;\r\n      margin-bottom: 0.8rem;\r\n    }\r\n    .pass-details-grid {\r\n      display: grid;\r\n      grid-template-columns: 1fr 1fr;\r\n      gap: 0.6rem;\r\n      font-size: 0.85rem;\r\n      margin-bottom: 0.6rem;\r\n    }\r\n    .pass-detail-item label {\r\n      font-size: 0.72rem;\r\n      color: var(--text-muted);\r\n      text-transform: uppercase;\r\n      font-family: 'JetBrains Mono', monospace;\r\n      display: block;\r\n      margin-bottom: 0.1rem;\r\n    }\r\n    .pass-detail-item div {\r\n      font-weight: 700;\r\n      color: #fff;\r\n    }\r\n    .wa-btn-group {\r\n      display: flex;\r\n      flex-direction: column;\r\n      gap: 0.65rem;\r\n      margin-top: 1.2rem;\r\n    }\r\n    .btn-wa-action {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 0.6rem;\r\n      padding: 0.85rem;\r\n      border-radius: 8px;\r\n      font-weight: 800;\r\n      font-size: 0.9rem;\r\n      text-decoration: none;\r\n      cursor: pointer;\r\n      border: none;\r\n      transition: all 0.2s ease;\r\n      width: 100%;\r\n    }\r\n    .btn-wa-student {\r\n      background: linear-gradient(135deg, #25d366, #128c7e);\r\n      color: #fff;\r\n      box-shadow: 0 0 15px rgba(37, 211, 102, 0.3);\r\n    }\r\n    .btn-wa-student:hover {\r\n      background: #25d366;\r\n      box-shadow: 0 0 25px rgba(37, 211, 102, 0.6);\r\n      transform: translateY(-1px);\r\n    }\r\n    @keyframes waPulse {\r\n      0%, 100% {\r\n        box-shadow: 0 0 15px rgba(37, 211, 102, 0.4);\r\n        transform: scale(1);\r\n      }\r\n      50% {\r\n        box-shadow: 0 0 28px rgba(37, 211, 102, 0.85);\r\n        transform: scale(1.02);\r\n      }\r\n    }\r\n    .btn-wa-admin {\r\n      background: rgba(15, 23, 42, 0.9);\r\n      border: 1px solid rgba(56, 189, 248, 0.3);\r\n      color: var(--aws-blue);\r\n    }\r\n    .btn-wa-admin:hover {\r\n      border-color: var(--aws-blue);\r\n      background: rgba(56, 189, 248, 0.1);\r\n    }\r\n    .btn-copy-pass {\r\n      background: transparent;\r\n      border: 1px solid var(--border-color);\r\n      color: var(--text-muted);\r\n      font-size: 0.82rem;\r\n      padding: 0.65rem;\r\n      border-radius: 6px;\r\n      cursor: pointer;\r\n      width: 100%;\r\n      transition: all 0.2s;\r\n    }\r\n    .btn-copy-pass:hover {\r\n      color: #fff;\r\n      border-color: var(--aws-blue);\r\n    }\r\n\r\n    footer {\r\n      text-align: center;\r\n      padding: 1.5rem;\r\n      color: var(--text-muted);\r\n      font-size: 0.8rem;\r\n      border-top: 1px solid var(--border-color);\r\n    }\r\n  </style>\r\n</head>\r\n<body>\r\n\r\n  <div class=\"bg-grid\"></div>\r\n  <div class=\"glow-aura\"></div>\r\n\r\n  <!-- Header -->\r\n  <header>\r\n    <div class=\"logo\">\r\n      <span class=\"logo-badge\">AWS</span>\r\n      <span class=\"logo-text\">Student <span>Builder</span></span>\r\n    </div>\r\n    <div style=\"display: flex; gap: 0.8rem; align-items: center;\">\r\n      <a href=\"admin.html\" class=\"admin-link-btn\" title=\"Open Admin Panel\">\r\n        ⚡ Admin Panel ↗\r\n      </a>\r\n    </div>\r\n  </header>\r\n\r\n  <!-- Hero Content -->\r\n  <main class=\"hero\">\r\n    <div class=\"status-badge\">\r\n      <span class=\"pulse-dot\"></span> Official Campus Event\r\n    </div>\r\n\r\n    <h1>AWS Student Builder <br><span class=\"highlight\">Community Day</span></h1>\r\n    <p class=\"subtitle\">Join us at Rungta University for cloud architecture workshops, hands-on serverless labs, and peer networking.</p>\r\n    \r\n    <button class=\"btn-primary\" id=\"openRegBtn\">\r\n      Register Now <span>→</span>\r\n    </button>\r\n\r\n    <!-- Bento Grid -->\r\n    <div class=\"bento-grid\">\r\n      <div class=\"bento-card\" id=\"locationCard\">\r\n        <div class=\"card-icon\">📍</div>\r\n        <h3>Campus Location <span>↗</span></h3>\r\n        <p>Rungta University Campus. Tap to open map navigation.</p>\r\n      </div>\r\n\r\n      <div class=\"bento-card\" id=\"highlightsCard\">\r\n        <div class=\"card-icon\">💡</div>\r\n        <h3>Event Highlights <span>↗</span></h3>\r\n        <p>Cloud workshops, hands-on serverless labs & peer tech networking.</p>\r\n      </div>\r\n\r\n      <div class=\"bento-card\" id=\"entryCard\">\r\n        <div class=\"card-icon\">🎟️</div>\r\n        <h3>Free Student Pass <span>↗</span></h3>\r\n        <p>100% free pass for all university students. Click to reserve your seat.</p>\r\n      </div>\r\n    </div>\r\n  </main>\r\n\r\n  <!-- REGISTRATION MODAL (MATCHING SCREENSHOT) -->\r\n  <div class=\"modal-overlay\" id=\"regModal\">\r\n    <div class=\"blueprint-modal\">\r\n      <button class=\"close-modal\" id=\"closeRegBtn\">&times;</button>\r\n      \r\n      <div class=\"step-header-img\">\r\n        <div class=\"step-icon-img\">⬡</div>\r\n        <div>\r\n          <h2>Step 1: Student Details</h2>\r\n          <p class=\"desc\">Fill in your official university details to reserve your seat for AWS Community Day.</p>\r\n        </div>\r\n      </div>\r\n\r\n      <form id=\"registrationForm\">\r\n        <div class=\"bp-group\">\r\n          <label for=\"name\">Full Name <span class=\"req\">*</span></label>\r\n          <input type=\"text\" id=\"name\" required placeholder=\"Enter your full name\">\r\n        </div>\r\n        \r\n        <div class=\"bp-group\">\r\n          <label for=\"email\">Email Address <span class=\"req\">*</span></label>\r\n          <input type=\"email\" id=\"email\" required placeholder=\"student@rungta.ac.in\">\r\n        </div>\r\n\r\n        <div class=\"bp-group\">\r\n          <label for=\"phone\">Mobile Number <span class=\"req\">*</span></label>\r\n          <input type=\"tel\" id=\"phone\" pattern=\"[0-9]{10}\" required placeholder=\"10-digit Mobile Number\">\r\n        </div>\r\n\r\n        <div class=\"bp-group\">\r\n          <label for=\"branch\">Select Your Branch <span class=\"req\">*</span></label>\r\n          <select id=\"branch\" required>\r\n            <option value=\"\">Select branch from dropdown</option>\r\n            <option value=\"CSE\">CSE (Computer Science)</option>\r\n            <option value=\"IT\">Information Technology</option>\r\n            <option value=\"AI_DS\">AI & Data Science</option>\r\n            <option value=\"ECE\">ECE</option>\r\n            <option value=\"EEE\">EEE / Electrical</option>\r\n            <option value=\"MECH\">Mechanical</option>\r\n            <option value=\"CIVIL\">Civil</option>\r\n            <option value=\"OTHER\">Other</option>\r\n          </select>\r\n        </div>\r\n\r\n        <div class=\"bp-row\">\r\n          <div class=\"bp-group\">\r\n            <label for=\"year\">Year <span class=\"req\">*</span></label>\r\n            <select id=\"year\" required>\r\n              <option value=\"\">Select</option>\r\n              <option value=\"1\">1st Year</option>\r\n              <option value=\"2\">2nd Year</option>\r\n              <option value=\"3\">3rd Year</option>\r\n              <option value=\"4\">4th Year</option>\r\n            </select>\r\n          </div>\r\n\r\n          <div class=\"bp-group\">\r\n            <label for=\"section\">Section <span class=\"req\">*</span></label>\r\n            <input type=\"text\" id=\"section\" required placeholder=\"e.g. A, B, C\">\r\n          </div>\r\n        </div>\r\n\r\n        <button type=\"submit\" class=\"bp-btn-action\" style=\"margin-top: 0.5rem;\">\r\n          CONFIRM REGISTRATION &rarr;\r\n        </button>\r\n      </form>\r\n\r\n      <!-- Digital Pass & WhatsApp Delivery -->\r\n      <div class=\"pass-container\" id=\"passContainer\">\r\n        <div style=\"text-align: center; margin-bottom: 0.8rem;\">\r\n          <div style=\"font-size: 2.2rem; margin-bottom: 0.2rem;\">🎉</div>\r\n          <h2 style=\"font-size: 1.3rem; color: #fff;\">Registration Confirmed!</h2>\r\n          <p style=\"color: #94a3b8; font-size: 0.82rem;\">Your official student entry pass has been generated.</p>\r\n        </div>\r\n\r\n        <div class=\"pass-card-box\">\r\n          <div style=\"display: flex; justify-content: space-between; align-items: center;\">\r\n            <span class=\"pass-badge\" id=\"displayPassId\">#AWS-RU-0000</span>\r\n            <span style=\"font-size: 0.72rem; color: #38bdf8; font-family: 'JetBrains Mono', monospace;\">CONFIRMED</span>\r\n          </div>\r\n          <div class=\"pass-details-grid\">\r\n            <div class=\"pass-detail-item\">\r\n              <label>Student</label>\r\n              <div id=\"displayName\">---</div>\r\n            </div>\r\n            <div class=\"pass-detail-item\">\r\n              <label>Branch</label>\r\n              <div id=\"displayBranch\">---</div>\r\n            </div>\r\n            <div class=\"pass-detail-item\">\r\n              <label>Year & Sec</label>\r\n              <div id=\"displayYearSec\">---</div>\r\n            </div>\r\n            <div class=\"pass-detail-item\">\r\n              <label>Mobile</label>\r\n              <div id=\"displayPhone\">---</div>\r\n            </div>\r\n          </div>\r\n          <div style=\"border-top: 1px dashed rgba(255,255,255,0.1); padding-top: 0.6rem; font-size: 0.78rem; color: var(--text-muted);\">\r\n            📍 Venue: Rungta University Campus\r\n          </div>\r\n        </div>\r\n\r\n        <!-- WhatsApp Action Buttons -->\r\n        <div class=\"wa-btn-group\">\r\n          <a href=\"#\" target=\"_blank\" class=\"btn-wa-action btn-wa-student\" id=\"waAdminDirectLink\" style=\"font-size: 0.95rem;\">\r\n            <span>💬</span> Open in WhatsApp &rarr;\r\n          </a>\r\n\r\n          <button type=\"button\" class=\"btn-copy-pass\" id=\"copyPassBtn\">\r\n            📋 Copy Pass Details to Clipboard\r\n          </button>\r\n          \r\n          <button type=\"button\" class=\"btn-copy-pass\" id=\"registerAnotherBtn\" style=\"border-color: transparent;\">\r\n            &larr; Register Another Student\r\n          </button>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- HIGHLIGHTS MODAL -->\r\n  <div class=\"modal-overlay\" id=\"highlightsModal\">\r\n    <div class=\"highlights-modal-card\">\r\n      <button class=\"close-modal\" id=\"closeHighlightsBtn\">&times;</button>\r\n      <h2 style=\"font-size: 1.3rem; font-weight: 800; color: var(--aws-blue);\">What to Expect</h2>\r\n      \r\n      <ul class=\"highlights-list\">\r\n        <li><strong>Cloud Fundamentals:</strong> Core AWS cloud architecture and scalable infrastructure.</li>\r\n        <li><strong>Hands-on Labs:</strong> Deploy real applications live on AWS Serverless.</li>\r\n        <li><strong>Generative AI:</strong> Learn how to build intelligent apps with AWS AI services.</li>\r\n        <li><strong>Community Networking:</strong> Connect with cloud mentors and student developers.</li>\r\n      </ul>\r\n\r\n      <button class=\"btn-primary\" id=\"modalRegBtn\" style=\"width: 100%; justify-content: center; margin-top: 0.5rem;\">\r\n        Get Registration Pass\r\n      </button>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- Footer -->\r\n  <footer>\r\n    &copy; AWS Student Builder Group — Rungta University Chapter &bull; <a href=\"admin.html\" style=\"color: var(--aws-blue); text-decoration: none; font-weight: 600;\">Admin Console</a>\r\n  </footer>\r\n\r\n  <script>\r\n    const TARGET_ADMIN_WHATSAPP = '919343756202';\r\n\r\n    // Document Elements\r\n    const regModal = document.getElementById('regModal');\r\n    const highlightsModal = document.getElementById('highlightsModal');\r\n    const registrationForm = document.getElementById('registrationForm');\r\n    const stepHeader = document.querySelector('.step-header-img');\r\n    const passContainer = document.getElementById('passContainer');\r\n    const displayPassId = document.getElementById('displayPassId');\r\n    const displayName = document.getElementById('displayName');\r\n    const displayBranch = document.getElementById('displayBranch');\r\n    const displayYearSec = document.getElementById('displayYearSec');\r\n    const displayPhone = document.getElementById('displayPhone');\r\n    const waAdminDirectLink = document.getElementById('waAdminDirectLink');\r\n    const copyPassBtn = document.getElementById('copyPassBtn');\r\n    const registerAnotherBtn = document.getElementById('registerAnotherBtn');\r\n\r\n    let currentWhatsAppText = '';\r\n\r\n    // Helper functions\r\n    function openModal(modal) {\r\n      if (modal) modal.classList.add('active');\r\n    }\r\n\r\n    function closeModal(modal) {\r\n      if (modal) {\r\n        modal.classList.remove('active');\r\n        if (modal === regModal) {\r\n          resetRegistrationModal();\r\n        }\r\n      }\r\n    }\r\n\r\n    function resetRegistrationModal() {\r\n      passContainer.style.display = 'none';\r\n      if (stepHeader) stepHeader.style.display = 'flex';\r\n      registrationForm.style.display = 'block';\r\n      registrationForm.reset();\r\n    }\r\n\r\n    // Button Click Handlers\r\n    document.getElementById('openRegBtn').addEventListener('click', function() { openModal(regModal); });\r\n    document.getElementById('entryCard').addEventListener('click', function() { openModal(regModal); });\r\n    document.getElementById('highlightsCard').addEventListener('click', function() { openModal(highlightsModal); });\r\n\r\n    document.getElementById('locationCard').addEventListener('click', function() {\r\n      window.open(\"https://maps.app.goo.gl/J7DvAnneeEWmdWRQ8\", \"_blank\");\r\n    });\r\n\r\n    document.getElementById('closeRegBtn').addEventListener('click', function() { closeModal(regModal); });\r\n    document.getElementById('closeHighlightsBtn').addEventListener('click', function() { closeModal(highlightsModal); });\r\n\r\n    document.getElementById('modalRegBtn').addEventListener('click', function() {\r\n      closeModal(highlightsModal);\r\n      openModal(regModal);\r\n    });\r\n\r\n    // Close on backdrop overlay click\r\n    window.addEventListener('click', function(e) {\r\n      if (e.target === regModal) closeModal(regModal);\r\n      if (e.target === highlightsModal) closeModal(highlightsModal);\r\n    });\r\n\r\n    // Copy Pass Details\r\n    copyPassBtn.addEventListener('click', function() {\r\n      if (navigator.clipboard && currentWhatsAppText) {\r\n        navigator.clipboard.writeText(currentWhatsAppText).then(() => {\r\n          copyPassBtn.textContent = '✅ Copied to Clipboard!';\r\n          setTimeout(() => {\r\n            copyPassBtn.textContent = '📋 Copy Pass Details to Clipboard';\r\n          }, 2500);\r\n        });\r\n      }\r\n    });\r\n\r\n    registerAnotherBtn.addEventListener('click', resetRegistrationModal);\r\n\r\n    // Handle Form Submit\r\n    registrationForm.addEventListener('submit', async function(e) {\r\n      e.preventDefault();\r\n\r\n      const submitBtn = registrationForm.querySelector('button[type=\"submit\"]');\r\n      const originalBtnText = submitBtn.innerHTML;\r\n      submitBtn.disabled = true;\r\n      submitBtn.innerHTML = 'SENDING TO WHATSAPP... ⏳';\r\n\r\n      const studentData = {\r\n        name: document.getElementById('name').value.trim(),\r\n        email: document.getElementById('email').value.trim(),\r\n        phone: document.getElementById('phone').value.trim(),\r\n        branch: document.getElementById('branch').value.trim(),\r\n        year: document.getElementById('year').value.trim(),\r\n        section: document.getElementById('section').value.trim()\r\n      };\r\n\r\n      try {\r\n        const response = await fetch('/api/register', {\r\n          method: 'POST',\r\n          headers: { 'Content-Type': 'application/json' },\r\n          body: JSON.stringify(studentData)\r\n        });\r\n\r\n        let data;\r\n        if (response.ok) {\r\n          data = await response.json();\r\n          if (data && data.registration) {\r\n            const localList = JSON.parse(localStorage.getItem('aws_registrations_cache') || '[]');\r\n            localList.unshift(data.registration);\r\n            localStorage.setItem('aws_registrations_cache', JSON.stringify(localList));\r\n          }\r\n        } else {\r\n          throw new Error('API request failed');\r\n        }\r\n\r\n        renderSuccessPass(data);\r\n      } catch (err) {\r\n        console.warn('Backend server unavailable, processing client-side:', err);\r\n        const randomId = 'AWS-RU-' + Math.floor(1000 + Math.random() * 9000);\r\n        const now = new Date();\r\n        const formattedDate = now.toLocaleString('en-IN', { timeZone: 'Asia/Kolkata', dateStyle: 'medium', timeStyle: 'short' });\r\n        \r\n        const fallbackRecord = {\r\n          id: randomId,\r\n          ...studentData,\r\n          registeredAt: now.toISOString(),\r\n          formattedDate: formattedDate\r\n        };\r\n\r\n        // Cache in browser localStorage\r\n        const localList = JSON.parse(localStorage.getItem('aws_registrations_cache') || '[]');\r\n        localList.unshift(fallbackRecord);\r\n        localStorage.setItem('aws_registrations_cache', JSON.stringify(localList));\r\n\r\n        const cleanPhone = studentData.phone.replace(/[^0-9]/g, '');\r\n        const phoneWithCountry = cleanPhone.length === 10 ? `91${cleanPhone}` : cleanPhone;\r\n        \r\n        const fallbackText = `🚀 *NEW REGISTRATION — AWS COMMUNITY DAY* 🚀\\n` +\r\n          `━━━━━━━━━━━━━━━━━━━━\\n` +\r\n          `🎟️ *Pass ID*: #${randomId}\\n` +\r\n          `👤 *Student Name*: ${studentData.name}\\n` +\r\n          `📱 *Mobile*: ${studentData.phone}\\n` +\r\n          `📧 *Email*: ${studentData.email}\\n` +\r\n          `🎓 *Branch*: ${studentData.branch}\\n` +\r\n          `📅 *Year*: ${studentData.year} Year | *Section*: ${studentData.section}\\n` +\r\n          `🏛️ *Venue*: Rungta University Campus\\n` +\r\n          `⏰ *Registered On*: ${formattedDate}\\n` +\r\n          `━━━━━━━━━━━━━━━━━━━━\\n` +\r\n          `✅ *Status*: Confirmed Student Pass`;\r\n\r\n        renderSuccessPass({\r\n          registration: fallbackRecord,\r\n          whatsappText: fallbackText,\r\n          studentWhatsAppUrl: `https://wa.me/${phoneWithCountry}?text=${encodeURIComponent(fallbackText)}`,\r\n          adminWhatsAppUrl: `https://wa.me/${TARGET_ADMIN_WHATSAPP}?text=${encodeURIComponent(fallbackText)}`\r\n        });\r\n      } finally {\r\n        submitBtn.disabled = false;\r\n        submitBtn.innerHTML = originalBtnText;\r\n      }\r\n    });\r\n\r\n    function renderSuccessPass(data) {\r\n      const reg = data.registration;\r\n      currentWhatsAppText = data.whatsappText;\r\n\r\n      displayPassId.textContent = `#${reg.id}`;\r\n      displayName.textContent = reg.name;\r\n      displayBranch.textContent = reg.branch;\r\n      displayYearSec.textContent = `${reg.year} Yr • Sec ${reg.section}`;\r\n      displayPhone.textContent = reg.phone;\r\n\r\n      // WhatsApp Link (Target: 9343756202)\r\n      const adminWaUrl = data.adminWhatsAppUrl || `https://wa.me/${TARGET_ADMIN_WHATSAPP}?text=${encodeURIComponent(currentWhatsAppText)}`;\r\n      waAdminDirectLink.href = adminWaUrl;\r\n\r\n      if (stepHeader) stepHeader.style.display = 'none';\r\n      registrationForm.style.display = 'none';\r\n      passContainer.style.display = 'block';\r\n\r\n      // Automatically launch WhatsApp\r\n      try {\r\n        window.open(adminWaUrl, '_blank');\r\n      } catch (e) {\r\n        console.log('Popup blocked, available via button');\r\n      }\r\n    }\r\n  </script>\r\n</body>\r\n</html>\r\n\r\n",
  adminHtml: "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Admin Dashboard — AWS Community Day @ Rungta University</title>\n  \n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@400;500;700&family=Plus+Jakarta+Sans:wght@300;400;500;600;700;800;900&display=swap\" rel=\"stylesheet\">\n  \n  <!-- SheetJS for local browser Excel export if needed -->\n  <script src=\"https://cdn.jsdelivr.net/npm/xlsx@0.18.5/dist/xlsx.full.min.js\"></script>\n\n  <style>\n    :root {\n      --bg-dark: #030712;\n      --card-bg: rgba(15, 23, 42, 0.75);\n      --card-border: rgba(56, 189, 248, 0.2);\n      --card-border-glow: rgba(56, 189, 248, 0.6);\n      --aws-orange: #ff9900;\n      --aws-blue: #38bdf8;\n      --emerald: #10b981;\n      --rose: #f43f5e;\n      --text-main: #ffffff;\n      --text-muted: #94a3b8;\n      --input-bg: #0f172a;\n    }\n\n    * {\n      box-sizing: border-box;\n      margin: 0;\n      padding: 0;\n      font-family: 'Plus Jakarta Sans', system-ui, sans-serif;\n    }\n\n    body {\n      background-color: var(--bg-dark);\n      color: var(--text-main);\n      min-height: 100vh;\n      display: flex;\n      flex-direction: column;\n    }\n\n    /* Ambient Blueprint Grid */\n    .bg-grid {\n      position: fixed;\n      inset: 0;\n      background-image: \n        linear-gradient(to right, rgba(255, 255, 255, 0.03) 1px, transparent 1px),\n        linear-gradient(to bottom, rgba(255, 255, 255, 0.03) 1px, transparent 1px);\n      background-size: 36px 36px;\n      z-index: -1;\n      pointer-events: none;\n    }\n\n    .glow-aura {\n      position: fixed;\n      top: -15%;\n      right: 15%;\n      width: 500px;\n      height: 500px;\n      background: radial-gradient(circle, rgba(56, 189, 248, 0.12) 0%, rgba(3, 105, 161, 0.04) 50%, transparent 70%);\n      filter: blur(80px);\n      z-index: -1;\n      pointer-events: none;\n    }\n\n    /* Header */\n    header {\n      display: flex;\n      justify-content: space-between;\n      align-items: center;\n      padding: 1.1rem 2rem;\n      background: rgba(3, 7, 18, 0.9);\n      border-bottom: 1px solid var(--card-border);\n      position: sticky;\n      top: 0;\n      z-index: 100;\n      backdrop-filter: blur(16px);\n      flex-wrap: wrap;\n      gap: 1rem;\n    }\n\n    .header-left {\n      display: flex;\n      align-items: center;\n      gap: 1rem;\n    }\n\n    .logo-badge {\n      background: linear-gradient(135deg, var(--aws-orange), #ff5500);\n      color: #000;\n      font-size: 0.72rem;\n      font-weight: 900;\n      padding: 0.25rem 0.6rem;\n      border-radius: 6px;\n      text-transform: uppercase;\n      letter-spacing: 0.5px;\n    }\n\n    .logo-text {\n      font-weight: 800;\n      font-size: 1.15rem;\n    }\n\n    .logo-text span {\n      color: var(--aws-blue);\n    }\n\n    .admin-pill {\n      background: rgba(56, 189, 248, 0.12);\n      border: 1px solid var(--card-border-glow);\n      color: var(--aws-blue);\n      font-size: 0.75rem;\n      font-weight: 700;\n      padding: 0.2rem 0.6rem;\n      border-radius: 99px;\n      font-family: 'JetBrains Mono', monospace;\n      display: inline-flex;\n      align-items: center;\n      gap: 0.4rem;\n    }\n\n    .header-actions {\n      display: flex;\n      align-items: center;\n      gap: 0.75rem;\n      flex-wrap: wrap;\n    }\n\n    /* Buttons */\n    .btn {\n      padding: 0.6rem 1.1rem;\n      border-radius: 8px;\n      font-size: 0.85rem;\n      font-weight: 700;\n      cursor: pointer;\n      display: inline-flex;\n      align-items: center;\n      gap: 0.5rem;\n      text-decoration: none;\n      transition: all 0.2s ease;\n      border: 1px solid transparent;\n      outline: none;\n    }\n\n    .btn-outline {\n      background: rgba(15, 23, 42, 0.8);\n      border-color: var(--card-border);\n      color: var(--text-main);\n    }\n\n    .btn-outline:hover {\n      border-color: var(--card-border-glow);\n      background: rgba(30, 41, 59, 0.9);\n    }\n\n    .btn-excel {\n      background: linear-gradient(135deg, #107c41, #15803d);\n      color: #ffffff;\n      border-color: rgba(34, 197, 94, 0.4);\n      box-shadow: 0 0 15px rgba(22, 163, 74, 0.3);\n    }\n\n    .btn-excel:hover {\n      background: #16a34a;\n      transform: translateY(-1px);\n      box-shadow: 0 0 20px rgba(22, 163, 74, 0.5);\n    }\n\n    .btn-whatsapp {\n      background: linear-gradient(135deg, #25d366, #128c7e);\n      color: #ffffff;\n    }\n\n    .btn-whatsapp:hover {\n      background: #25d366;\n      box-shadow: 0 0 18px rgba(37, 211, 102, 0.4);\n    }\n\n    .btn-primary {\n      background: linear-gradient(135deg, #0284c7, #0369a1);\n      color: #ffffff;\n    }\n\n    .btn-primary:hover {\n      background: #0284c7;\n    }\n\n    /* Main Container */\n    .container {\n      max-width: 1300px;\n      width: 100%;\n      margin: 0 auto;\n      padding: 2rem 1.5rem 3rem;\n      flex: 1;\n    }\n\n    /* Stats Grid */\n    .stats-grid {\n      display: grid;\n      grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));\n      gap: 1.2rem;\n      margin-bottom: 2rem;\n    }\n\n    .stat-card {\n      background: var(--card-bg);\n      border: 1px solid var(--card-border);\n      border-radius: 14px;\n      padding: 1.4rem;\n      position: relative;\n      overflow: hidden;\n      transition: border-color 0.2s;\n    }\n\n    .stat-card:hover {\n      border-color: var(--card-border-glow);\n    }\n\n    .stat-header {\n      display: flex;\n      justify-content: space-between;\n      align-items: center;\n      margin-bottom: 0.8rem;\n    }\n\n    .stat-title {\n      color: var(--text-muted);\n      font-size: 0.82rem;\n      font-weight: 700;\n      text-transform: uppercase;\n      letter-spacing: 0.5px;\n    }\n\n    .stat-icon {\n      font-size: 1.3rem;\n    }\n\n    .stat-value {\n      font-size: 2.2rem;\n      font-weight: 900;\n      font-family: 'JetBrains Mono', monospace;\n      color: #ffffff;\n      line-height: 1;\n      margin-bottom: 0.4rem;\n    }\n\n    .stat-subtext {\n      color: var(--text-muted);\n      font-size: 0.8rem;\n    }\n\n    .stat-subtext strong {\n      color: var(--aws-blue);\n    }\n\n    /* Table Toolbar */\n    .toolbar-panel {\n      background: var(--card-bg);\n      border: 1px solid var(--card-border);\n      border-radius: 14px 14px 0 0;\n      padding: 1.2rem 1.4rem;\n      display: flex;\n      justify-content: space-between;\n      align-items: center;\n      flex-wrap: wrap;\n      gap: 1rem;\n    }\n\n    .toolbar-title {\n      font-size: 1.15rem;\n      font-weight: 800;\n      display: flex;\n      align-items: center;\n      gap: 0.6rem;\n    }\n\n    .toolbar-filters {\n      display: flex;\n      align-items: center;\n      gap: 0.8rem;\n      flex-wrap: wrap;\n      flex: 1;\n      justify-content: flex-end;\n    }\n\n    .search-box {\n      position: relative;\n      min-width: 240px;\n      max-width: 320px;\n      flex: 1;\n    }\n\n    .search-box input {\n      width: 100%;\n      padding: 0.55rem 0.9rem 0.55rem 2.2rem;\n      background: var(--input-bg);\n      border: 1px solid var(--card-border);\n      border-radius: 8px;\n      color: #fff;\n      font-size: 0.85rem;\n      outline: none;\n      transition: border-color 0.2s;\n    }\n\n    .search-box input:focus {\n      border-color: var(--aws-blue);\n    }\n\n    .search-box span {\n      position: absolute;\n      left: 0.75rem;\n      top: 50%;\n      transform: translateY(-50%);\n      color: var(--text-muted);\n      font-size: 0.85rem;\n    }\n\n    .filter-select {\n      background: var(--input-bg);\n      border: 1px solid var(--card-border);\n      border-radius: 8px;\n      color: #fff;\n      padding: 0.55rem 0.85rem;\n      font-size: 0.85rem;\n      outline: none;\n      cursor: pointer;\n    }\n\n    .filter-select:focus {\n      border-color: var(--aws-blue);\n    }\n\n    /* Table Container */\n    .table-container {\n      background: var(--card-bg);\n      border: 1px solid var(--card-border);\n      border-top: none;\n      border-radius: 0 0 14px 14px;\n      overflow-x: auto;\n    }\n\n    table {\n      width: 100%;\n      border-collapse: collapse;\n      text-align: left;\n      font-size: 0.88rem;\n    }\n\n    thead {\n      background: rgba(3, 7, 18, 0.7);\n      border-bottom: 1px solid var(--card-border);\n    }\n\n    th {\n      padding: 0.9rem 1.2rem;\n      color: var(--text-muted);\n      font-weight: 700;\n      font-size: 0.78rem;\n      text-transform: uppercase;\n      letter-spacing: 0.5px;\n      white-space: nowrap;\n    }\n\n    tbody tr {\n      border-bottom: 1px solid rgba(255, 255, 255, 0.05);\n      transition: background 0.15s ease;\n    }\n\n    tbody tr:hover {\n      background: rgba(56, 189, 248, 0.04);\n    }\n\n    td {\n      padding: 0.9rem 1.2rem;\n      vertical-align: middle;\n      white-space: nowrap;\n    }\n\n    .pass-tag {\n      background: rgba(56, 189, 248, 0.12);\n      border: 1px solid rgba(56, 189, 248, 0.3);\n      color: var(--aws-blue);\n      font-family: 'JetBrains Mono', monospace;\n      font-weight: 700;\n      font-size: 0.8rem;\n      padding: 0.25rem 0.55rem;\n      border-radius: 6px;\n      display: inline-flex;\n      align-items: center;\n      gap: 0.3rem;\n    }\n\n    .student-name {\n      font-weight: 700;\n      color: #ffffff;\n    }\n\n    .student-meta {\n      color: var(--text-muted);\n      font-size: 0.78rem;\n      margin-top: 0.15rem;\n    }\n\n    .badge-branch {\n      display: inline-block;\n      padding: 0.2rem 0.55rem;\n      border-radius: 6px;\n      font-size: 0.75rem;\n      font-weight: 700;\n      background: rgba(255, 153, 0, 0.15);\n      border: 1px solid rgba(255, 153, 0, 0.4);\n      color: var(--aws-orange);\n    }\n\n    .badge-year {\n      display: inline-block;\n      padding: 0.2rem 0.55rem;\n      border-radius: 6px;\n      font-size: 0.75rem;\n      font-weight: 700;\n      background: rgba(99, 102, 241, 0.15);\n      border: 1px solid rgba(99, 102, 241, 0.4);\n      color: #a5b4fc;\n    }\n\n    .action-btn {\n      display: inline-flex;\n      align-items: center;\n      justify-content: center;\n      width: 32px;\n      height: 32px;\n      border-radius: 6px;\n      border: 1px solid var(--card-border);\n      background: var(--input-bg);\n      color: var(--text-main);\n      cursor: pointer;\n      font-size: 0.95rem;\n      transition: all 0.2s;\n      text-decoration: none;\n    }\n\n    .action-btn.whatsapp:hover {\n      background: #25d366;\n      border-color: #25d366;\n      color: #fff;\n    }\n\n    .action-btn.delete:hover {\n      background: var(--rose);\n      border-color: var(--rose);\n      color: #fff;\n    }\n\n    /* Empty state */\n    .empty-state {\n      text-align: center;\n      padding: 4rem 1.5rem;\n      color: var(--text-muted);\n    }\n\n    .empty-state-icon {\n      font-size: 3rem;\n      margin-bottom: 1rem;\n      opacity: 0.7;\n    }\n\n    /* Modals */\n    .modal-overlay {\n      display: none;\n      position: fixed;\n      inset: 0;\n      background: rgba(3, 7, 18, 0.85);\n      z-index: 1000;\n      justify-content: center;\n      align-items: center;\n      padding: 1.2rem;\n      backdrop-filter: blur(8px);\n    }\n\n    .modal-overlay.active {\n      display: flex !important;\n    }\n\n    .modal-card {\n      background: #0f172a;\n      border: 1px solid var(--card-border-glow);\n      border-radius: 14px;\n      padding: 2rem;\n      width: 100%;\n      max-width: 480px;\n      position: relative;\n      box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.8);\n    }\n\n    .modal-card h2 {\n      font-size: 1.25rem;\n      font-weight: 800;\n      margin-bottom: 0.5rem;\n      color: #fff;\n    }\n\n    .modal-card p.sub {\n      color: var(--text-muted);\n      font-size: 0.85rem;\n      margin-bottom: 1.4rem;\n      line-height: 1.4;\n    }\n\n    .form-group {\n      margin-bottom: 1.2rem;\n    }\n\n    .form-group label {\n      display: block;\n      margin-bottom: 0.4rem;\n      font-size: 0.82rem;\n      font-weight: 700;\n      color: var(--text-muted);\n    }\n\n    .form-group input {\n      width: 100%;\n      padding: 0.75rem 0.9rem;\n      background: #030712;\n      border: 1px solid var(--card-border);\n      border-radius: 8px;\n      color: #fff;\n      font-size: 0.9rem;\n      outline: none;\n    }\n\n    .form-group input:focus {\n      border-color: var(--aws-blue);\n    }\n\n    .modal-actions {\n      display: flex;\n      justify-content: flex-end;\n      gap: 0.75rem;\n      margin-top: 1.5rem;\n    }\n\n    .close-btn {\n      position: absolute;\n      top: 1rem;\n      right: 1.2rem;\n      background: transparent;\n      border: none;\n      color: var(--text-muted);\n      font-size: 1.5rem;\n      cursor: pointer;\n    }\n\n    .close-btn:hover {\n      color: #fff;\n    }\n\n    /* Toast Notification */\n    .toast {\n      position: fixed;\n      bottom: 24px;\n      right: 24px;\n      background: rgba(15, 23, 42, 0.95);\n      border: 1px solid var(--card-border-glow);\n      color: #ffffff;\n      padding: 0.9rem 1.4rem;\n      border-radius: 10px;\n      font-size: 0.88rem;\n      font-weight: 600;\n      display: flex;\n      align-items: center;\n      gap: 0.6rem;\n      box-shadow: 0 10px 25px rgba(0, 0, 0, 0.5);\n      z-index: 2000;\n      transform: translateY(100px);\n      opacity: 0;\n      transition: all 0.25s cubic-bezier(0.16, 1, 0.3, 1);\n    }\n\n    .toast.show {\n      transform: translateY(0);\n      opacity: 1;\n    }\n\n    /* LOGIN SCREEN STYLING */\n    .login-wrapper {\n      min-height: 100vh;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      padding: 1.5rem;\n      position: relative;\n      z-index: 10;\n    }\n\n    .login-box {\n      background: rgba(15, 23, 42, 0.9);\n      border: 1px solid var(--card-border-glow);\n      border-radius: 16px;\n      padding: 2.4rem 2rem;\n      width: 100%;\n      max-width: 420px;\n      box-shadow: 0 25px 60px rgba(0, 0, 0, 0.85);\n      backdrop-filter: blur(16px);\n      text-align: center;\n      animation: modalFadeIn 0.3s ease;\n    }\n\n    .login-header-logo {\n      display: inline-flex;\n      align-items: center;\n      gap: 0.6rem;\n      margin-bottom: 1.2rem;\n    }\n\n    .login-box h2 {\n      font-size: 1.35rem;\n      font-weight: 800;\n      color: #ffffff;\n      margin-bottom: 0.4rem;\n    }\n\n    .login-box p.login-sub {\n      color: var(--text-muted);\n      font-size: 0.84rem;\n      margin-bottom: 1.6rem;\n    }\n\n    .login-form-group {\n      text-align: left;\n      margin-bottom: 1.2rem;\n    }\n\n    .login-form-group label {\n      display: block;\n      font-size: 0.8rem;\n      font-weight: 700;\n      color: var(--text-muted);\n      margin-bottom: 0.4rem;\n      font-family: 'JetBrains Mono', monospace;\n    }\n\n    .login-form-group input {\n      width: 100%;\n      padding: 0.8rem 0.95rem;\n      background: #030712;\n      border: 1px solid var(--card-border);\n      border-radius: 8px;\n      color: #fff;\n      font-size: 0.92rem;\n      outline: none;\n      transition: border-color 0.2s;\n    }\n\n    .login-form-group input:focus {\n      border-color: var(--aws-blue);\n      box-shadow: 0 0 15px rgba(56, 189, 248, 0.2);\n    }\n\n    .btn-login-submit {\n      width: 100%;\n      background: linear-gradient(135deg, #0284c7 0%, #0369a1 50%, #6366f1 100%);\n      color: #fff;\n      border: none;\n      padding: 0.85rem;\n      font-size: 0.92rem;\n      font-weight: 800;\n      border-radius: 8px;\n      cursor: pointer;\n      margin-top: 0.5rem;\n      transition: all 0.2s ease;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      gap: 0.5rem;\n    }\n\n    .btn-login-submit:hover {\n      box-shadow: 0 0 25px rgba(56, 189, 248, 0.6);\n      transform: translateY(-1px);\n    }\n\n    .login-alert {\n      display: none;\n      background: rgba(244, 63, 94, 0.15);\n      border: 1px solid rgba(244, 63, 94, 0.4);\n      color: #fda4af;\n      padding: 0.6rem 0.8rem;\n      border-radius: 8px;\n      font-size: 0.82rem;\n      margin-bottom: 1.2rem;\n      text-align: left;\n    }\n\n    .default-creds-hint {\n      margin-top: 1.5rem;\n      background: rgba(56, 189, 248, 0.08);\n      border: 1px dashed rgba(56, 189, 248, 0.3);\n      padding: 0.8rem;\n      border-radius: 8px;\n      font-size: 0.78rem;\n      color: var(--text-muted);\n      line-height: 1.5;\n    }\n\n    .default-creds-hint code {\n      color: var(--aws-blue);\n      font-weight: 700;\n      font-family: 'JetBrains Mono', monospace;\n    }\n\n    footer {\n      text-align: center;\n      padding: 1.5rem;\n      color: var(--text-muted);\n      font-size: 0.8rem;\n      border-top: 1px solid var(--card-border);\n    }\n  </style>\n</head>\n<body>\n\n  <div class=\"bg-grid\"></div>\n  <div class=\"glow-aura\"></div>\n\n  <!-- LOGIN VIEW -->\n  <div id=\"loginView\" class=\"login-wrapper\">\n    <div class=\"login-box\">\n      <div class=\"login-header-logo\">\n        <span class=\"logo-badge\">AWS</span>\n        <div class=\"logo-text\">Student <span>Builder</span></div>\n      </div>\n      \n      <h2>🔐 Admin Security Gateway</h2>\n      <p class=\"login-sub\">Enter your authorized credentials to access the registration database & tools.</p>\n\n      <div class=\"login-alert\" id=\"loginAlert\">\n        ⚠️ Invalid username or password. Please try again.\n      </div>\n\n      <form id=\"adminLoginForm\">\n        <div class=\"login-form-group\">\n          <label for=\"loginUsername\">ADMIN USERNAME</label>\n          <input type=\"text\" id=\"loginUsername\" placeholder=\"e.g. admin\" required autocomplete=\"username\" autofocus>\n        </div>\n\n        <div class=\"login-form-group\">\n          <label for=\"loginPassword\">PASSWORD</label>\n          <input type=\"password\" id=\"loginPassword\" placeholder=\"••••••••\" required autocomplete=\"current-password\">\n        </div>\n\n        <button type=\"submit\" class=\"btn-login-submit\" id=\"loginSubmitBtn\">\n          ⚡ SIGN IN TO DASHBOARD &rarr;\n        </button>\n      </form>\n\n      <div style=\"margin-top: 1.5rem;\">\n        <a href=\"index.html\" style=\"color: var(--aws-blue); text-decoration: none; font-size: 0.85rem; font-weight: 700;\">\n          &larr; Back to Registration Website\n        </a>\n      </div>\n    </div>\n  </div>\n\n  <!-- DASHBOARD VIEW -->\n  <div id=\"dashboardView\" style=\"display: none; min-height: 100vh; flex-direction: column;\">\n    <!-- Header -->\n    <header>\n      <div class=\"header-left\">\n        <span class=\"logo-badge\">AWS</span>\n        <div class=\"logo-text\">Student <span>Builder</span></div>\n        <span class=\"admin-pill\">⚡ ADMIN CONSOLE</span>\n      </div>\n\n      <div class=\"header-actions\">\n        <a href=\"index.html\" class=\"btn btn-outline\" target=\"_blank\" title=\"Open student registration website\">\n          🌐 View Live Site ↗\n        </a>\n        \n        <button class=\"btn btn-outline\" id=\"openSettingsBtn\" title=\"Set Admin WhatsApp Number\">\n          ⚙️ WhatsApp Settings\n        </button>\n\n        <!-- EXCEL EXPORT BUTTON -->\n        <button class=\"btn btn-excel\" id=\"exportExcelBtn\" title=\"Export registrations directly to formatted Excel\">\n          📊 Export to Excel (.xlsx)\n        </button>\n\n        <button class=\"btn btn-outline\" id=\"exportCsvBtn\" title=\"Download CSV format\">\n          📄 Export CSV\n        </button>\n\n        <!-- LOGOUT BUTTON -->\n        <button class=\"btn btn-outline\" id=\"logoutBtn\" style=\"border-color: rgba(244, 63, 94, 0.4); color: #fda4af;\" title=\"Log out from Admin Console\">\n          🚪 Logout\n        </button>\n      </div>\n    </header>\n\n  <!-- Main Content -->\n  <div class=\"container\">\n    <!-- Statistics Cards -->\n    <div class=\"stats-grid\">\n      <div class=\"stat-card\">\n        <div class=\"stat-header\">\n          <span class=\"stat-title\">Total Registrations</span>\n          <span class=\"stat-icon\">👥</span>\n        </div>\n        <div class=\"stat-value\" id=\"statTotal\">0</div>\n        <div class=\"stat-subtext\">Confirmed student passes issued</div>\n      </div>\n\n      <div class=\"stat-card\">\n        <div class=\"stat-header\">\n          <span class=\"stat-title\">Registered Today</span>\n          <span class=\"stat-icon\">⚡</span>\n        </div>\n        <div class=\"stat-value\" id=\"statToday\">0</div>\n        <div class=\"stat-subtext\">New signups recorded today</div>\n      </div>\n\n      <div class=\"stat-card\">\n        <div class=\"stat-header\">\n          <span class=\"stat-title\">Top Branch</span>\n          <span class=\"stat-icon\">🎓</span>\n        </div>\n        <div class=\"stat-value\" id=\"statTopBranch\" style=\"font-size: 1.5rem; padding-top: 0.4rem;\">None</div>\n        <div class=\"stat-subtext\" id=\"statTopBranchSub\">No branch data yet</div>\n      </div>\n\n      <div class=\"stat-card\">\n        <div class=\"stat-header\">\n          <span class=\"stat-title\">Admin WhatsApp</span>\n          <span class=\"stat-icon\">📱</span>\n        </div>\n        <div class=\"stat-value\" id=\"statWhatsApp\" style=\"font-size: 1.25rem; padding-top: 0.5rem; color: #25d366;\">\n          Not Set\n        </div>\n        <div class=\"stat-subtext\">Click 'WhatsApp Settings' to configure</div>\n      </div>\n    </div>\n\n    <!-- Table Toolbar -->\n    <div class=\"toolbar-panel\">\n      <div class=\"toolbar-title\">\n        <span>Registered Students</span>\n        <span class=\"pass-tag\" id=\"tableCountTag\">0 records</span>\n      </div>\n\n      <div class=\"toolbar-filters\">\n        <div class=\"search-box\">\n          <span>🔍</span>\n          <input type=\"text\" id=\"searchInput\" placeholder=\"Search by name, phone, email, pass ID...\">\n        </div>\n\n        <select id=\"branchFilter\" class=\"filter-select\">\n          <option value=\"\">All Branches</option>\n          <option value=\"CSE\">CSE</option>\n          <option value=\"IT\">IT</option>\n          <option value=\"AI_DS\">AI & Data Science</option>\n          <option value=\"ECE\">ECE</option>\n          <option value=\"EEE\">EEE</option>\n          <option value=\"MECH\">Mechanical</option>\n          <option value=\"CIVIL\">Civil</option>\n          <option value=\"OTHER\">Other</option>\n        </select>\n\n        <select id=\"yearFilter\" class=\"filter-select\">\n          <option value=\"\">All Years</option>\n          <option value=\"1\">1st Year</option>\n          <option value=\"2\">2nd Year</option>\n          <option value=\"3\">3rd Year</option>\n          <option value=\"4\">4th Year</option>\n        </select>\n\n        <button class=\"btn btn-outline\" id=\"refreshBtn\" title=\"Refresh data\">\n          🔄 Refresh\n        </button>\n      </div>\n    </div>\n\n    <!-- Table Container -->\n    <div class=\"table-container\">\n      <table>\n        <thead>\n          <tr>\n            <th>Pass ID</th>\n            <th>Student Name</th>\n            <th>Contact Details</th>\n            <th>Branch</th>\n            <th>Year & Sec</th>\n            <th>Date & Time</th>\n            <th style=\"text-align: right;\">Actions</th>\n          </tr>\n        </thead>\n        <tbody id=\"registrationsTableBody\">\n          <!-- Populated by JavaScript -->\n        </tbody>\n      </table>\n\n      <div class=\"empty-state\" id=\"emptyState\" style=\"display: none;\">\n        <div class=\"empty-state-icon\">📋</div>\n        <h3 style=\"color: #fff; margin-bottom: 0.4rem;\">No registrations found</h3>\n        <p>No students have registered yet or no records match your filter.</p>\n      </div>\n    </div>\n  </div>\n\n  <!-- WhatsApp Settings Modal -->\n  <div class=\"modal-overlay\" id=\"settingsModal\">\n    <div class=\"modal-card\">\n      <button class=\"close-btn\" id=\"closeSettingsModal\">&times;</button>\n      <h2>⚙️ WhatsApp & Event Settings</h2>\n      <p class=\"sub\">Configure the WhatsApp phone number where you want to receive registration details and inquiries.</p>\n\n      <form id=\"settingsForm\">\n        <div class=\"form-group\">\n          <label for=\"adminWhatsAppInput\">Admin WhatsApp Number (with Country Code):</label>\n          <input type=\"tel\" id=\"adminWhatsAppInput\" placeholder=\"e.g. 919876543210\" required>\n          <span style=\"font-size: 0.76rem; color: var(--text-muted); display: block; margin-top: 0.35rem;\">\n            Include 91 for India (e.g. 919826012345). No + or spaces needed.\n          </span>\n        </div>\n\n        <div class=\"modal-actions\">\n          <button type=\"button\" class=\"btn btn-outline\" id=\"cancelSettingsBtn\">Cancel</button>\n          <button type=\"submit\" class=\"btn btn-whatsapp\">Save WhatsApp Number</button>\n        </div>\n      </form>\n    </div>\n  </div>\n\n  <!-- Toast -->\n  <div class=\"toast\" id=\"toast\">\n    <span id=\"toastIcon\">✅</span>\n    <span id=\"toastMsg\">Operation successful</span>\n  </div>\n\n  <footer>\n    &copy; AWS Student Builder Group — Admin Control Room &bull; Rungta University\n  </footer>\n  </div><!-- /dashboardView -->\n\n  <script>\n    // State\n    let allRegistrations = [];\n    let settings = { adminWhatsApp: '919343756202' };\n\n    // Auth & View References\n    const loginView = document.getElementById('loginView');\n    const dashboardView = document.getElementById('dashboardView');\n    const adminLoginForm = document.getElementById('adminLoginForm');\n    const loginUsername = document.getElementById('loginUsername');\n    const loginPassword = document.getElementById('loginPassword');\n    const loginAlert = document.getElementById('loginAlert');\n    const loginSubmitBtn = document.getElementById('loginSubmitBtn');\n    const logoutBtn = document.getElementById('logoutBtn');\n\n    // DOM References\n    const tableBody = document.getElementById('registrationsTableBody');\n    const emptyState = document.getElementById('emptyState');\n    const searchInput = document.getElementById('searchInput');\n    const branchFilter = document.getElementById('branchFilter');\n    const yearFilter = document.getElementById('yearFilter');\n    const tableCountTag = document.getElementById('tableCountTag');\n    const statTotal = document.getElementById('statTotal');\n    const statToday = document.getElementById('statToday');\n    const statTopBranch = document.getElementById('statTopBranch');\n    const statTopBranchSub = document.getElementById('statTopBranchSub');\n    const statWhatsApp = document.getElementById('statWhatsApp');\n    const settingsModal = document.getElementById('settingsModal');\n    const settingsForm = document.getElementById('settingsForm');\n    const adminWhatsAppInput = document.getElementById('adminWhatsAppInput');\n    const toast = document.getElementById('toast');\n    const toastMsg = document.getElementById('toastMsg');\n    const toastIcon = document.getElementById('toastIcon');\n\n    // Show Toast\n    function showToast(msg, icon = '✅') {\n      toastMsg.textContent = msg;\n      toastIcon.textContent = icon;\n      toast.classList.add('show');\n      setTimeout(() => toast.classList.remove('show'), 3500);\n    }\n\n    // Fetch Registrations from server (with localStorage fallback)\n    async function loadData() {\n      const localList = JSON.parse(localStorage.getItem('aws_registrations_cache') || '[]');\n      try {\n        const res = await fetch('/api/registrations');\n        if (res.ok) {\n          const data = await res.json();\n          const serverList = data.registrations || [];\n          const map = new Map();\n          [...serverList, ...localList].forEach(item => {\n            if (item && item.id) map.set(item.id, item);\n          });\n          allRegistrations = Array.from(map.values());\n          settings = data.settings || {};\n          if (!settings.adminWhatsApp) settings.adminWhatsApp = '919343756202';\n          localStorage.setItem('aws_registrations_cache', JSON.stringify(allRegistrations));\n          localStorage.setItem('aws_settings_cache', JSON.stringify(settings));\n        } else {\n          throw new Error('Server returned non-200');\n        }\n      } catch (err) {\n        console.warn('Backend not reachable, loading from browser local cache:', err);\n        allRegistrations = localList;\n        settings = JSON.parse(localStorage.getItem('aws_settings_cache') || '{\"adminWhatsApp\":\"919343756202\"}');\n      }\n\n      updateUI();\n    }\n\n    // Update Dashboard Metrics and Table\n    function updateUI() {\n      // 1. Stats\n      const total = allRegistrations.length;\n      statTotal.textContent = total;\n\n      const todayStr = new Date().toISOString().slice(0, 10);\n      const todayCount = allRegistrations.filter(r => r.registeredAt && r.registeredAt.startsWith(todayStr)).length;\n      statToday.textContent = todayCount;\n\n      // Top Branch\n      const branchCounts = {};\n      allRegistrations.forEach(r => {\n        branchCounts[r.branch] = (branchCounts[r.branch] || 0) + 1;\n      });\n      let topBranch = null;\n      let topCount = 0;\n      for (const [branch, count] of Object.entries(branchCounts)) {\n        if (count > topCount) {\n          topBranch = branch;\n          topCount = count;\n        }\n      }\n      if (topBranch) {\n        statTopBranch.textContent = topBranch;\n        statTopBranchSub.textContent = `${topCount} student${topCount > 1 ? 's' : ''} enrolled`;\n      } else {\n        statTopBranch.textContent = 'None';\n        statTopBranchSub.textContent = 'No branch data yet';\n      }\n\n      // WhatsApp status\n      if (settings.adminWhatsApp) {\n        statWhatsApp.textContent = '+' + settings.adminWhatsApp;\n      } else {\n        statWhatsApp.textContent = 'Not Configured';\n      }\n\n      // 2. Filter Table\n      renderTable();\n    }\n\n    function renderTable() {\n      const q = searchInput.value.toLowerCase().trim();\n      const bFilter = branchFilter.value;\n      const yFilter = yearFilter.value;\n\n      const filtered = allRegistrations.filter(item => {\n        const matchesQuery = !q ||\n          (item.name && item.name.toLowerCase().includes(q)) ||\n          (item.email && item.email.toLowerCase().includes(q)) ||\n          (item.phone && item.phone.includes(q)) ||\n          (item.id && item.id.toLowerCase().includes(q)) ||\n          (item.branch && item.branch.toLowerCase().includes(q)) ||\n          (item.section && item.section.toLowerCase().includes(q));\n\n        const matchesBranch = !bFilter || item.branch === bFilter;\n        const matchesYear = !yFilter || item.year === yFilter;\n\n        return matchesQuery && matchesBranch && matchesYear;\n      });\n\n      tableCountTag.textContent = `${filtered.length} of ${allRegistrations.length}`;\n\n      if (filtered.length === 0) {\n        tableBody.innerHTML = '';\n        emptyState.style.display = 'block';\n        return;\n      }\n\n      emptyState.style.display = 'none';\n      tableBody.innerHTML = filtered.map(item => {\n        const cleanPhone = item.phone.replace(/[^0-9]/g, '');\n        const phoneWithCountry = cleanPhone.length === 10 ? `91${cleanPhone}` : cleanPhone;\n        \n        const whatsappMsg = `Hi ${item.name}! This is from the AWS Student Builder Community Day team @ Rungta University. Your Entry Pass ID is #${item.id}. Let us know if you have any questions!`;\n        const waLink = `https://wa.me/${phoneWithCountry}?text=${encodeURIComponent(whatsappMsg)}`;\n\n        return `\n          <tr>\n            <td>\n              <span class=\"pass-tag\">🎟️ ${item.id}</span>\n            </td>\n            <td>\n              <div class=\"student-name\">${escapeHtml(item.name)}</div>\n            </td>\n            <td>\n              <div style=\"font-size: 0.85rem; color: #fff;\">${escapeHtml(item.phone)}</div>\n              <div class=\"student-meta\">${escapeHtml(item.email)}</div>\n            </td>\n            <td>\n              <span class=\"badge-branch\">${escapeHtml(item.branch)}</span>\n            </td>\n            <td>\n              <span class=\"badge-year\">${item.year} Yr &bull; Sec ${escapeHtml(item.section)}</span>\n            </td>\n            <td>\n              <div style=\"color: var(--text-muted); font-size: 0.82rem;\">${item.formattedDate || (item.registeredAt ? new Date(item.registeredAt).toLocaleDateString() : 'N/A')}</div>\n            </td>\n            <td style=\"text-align: right;\">\n              <div style=\"display: inline-flex; gap: 0.4rem;\">\n                <a href=\"${waLink}\" target=\"_blank\" class=\"action-btn whatsapp\" title=\"Chat with ${escapeHtml(item.name)} on WhatsApp\">\n                  💬\n                </a>\n                <button onclick=\"deleteRecord('${item.id}')\" class=\"action-btn delete\" title=\"Delete record\">\n                  🗑️\n                </button>\n              </div>\n            </td>\n          </tr>\n        `;\n      }).join('');\n    }\n\n    function escapeHtml(str) {\n      if (!str) return '';\n      return String(str).replace(/[&<>\"']/g, m => ({\n        '&': '&amp;',\n        '<': '&lt;',\n        '>': '&gt;',\n        '\"': '&quot;',\n        \"'\": '&#39;'\n      })[m]);\n    }\n\n    // Delete Record\n    async function deleteRecord(id) {\n      if (!confirm(`Are you sure you want to delete registration ${id}?`)) return;\n\n      try {\n        const res = await fetch(`/api/registrations/${id}`, { method: 'DELETE' });\n        if (res.ok) {\n          showToast(`Deleted ${id}`, '🗑️');\n        }\n      } catch (e) {\n        console.warn('Backend delete failed, removing locally:', e);\n      }\n\n      allRegistrations = allRegistrations.filter(r => r.id !== id);\n      localStorage.setItem('aws_registrations_cache', JSON.stringify(allRegistrations));\n      updateUI();\n    }\n\n    // EXCEL EXPORT\n    document.getElementById('exportExcelBtn').addEventListener('click', async function() {\n      if (allRegistrations.length === 0) {\n        alert('No registrations available to export.');\n        return;\n      }\n\n      // Try server-side export first for native server response\n      try {\n        const response = await fetch('/api/export-excel');\n        if (response.ok) {\n          const blob = await response.blob();\n          const url = window.URL.createObjectURL(blob);\n          const a = document.createElement('a');\n          a.href = url;\n          a.download = `AWS_Community_Day_Registrations_${new Date().toISOString().slice(0, 10)}.xlsx`;\n          document.body.appendChild(a);\n          a.click();\n          a.remove();\n          showToast('Excel (.xlsx) downloaded successfully! 📊');\n          return;\n        }\n      } catch (err) {\n        console.warn('Server Excel endpoint error, falling back to client-side SheetJS:', err);\n      }\n\n      // Client-side SheetJS fallback\n      if (typeof XLSX !== 'undefined') {\n        const exportData = allRegistrations.map((item, idx) => ({\n          'S.No': idx + 1,\n          'Pass ID': item.id,\n          'Full Name': item.name,\n          'Email': item.email,\n          'Mobile': item.phone,\n          'Branch': item.branch,\n          'Year': `${item.year} Year`,\n          'Section': item.section,\n          'Registered On': item.formattedDate || item.registeredAt\n        }));\n\n        const ws = XLSX.utils.json_to_sheet(exportData);\n        ws['!cols'] = [\n          { wch: 6 }, { wch: 15 }, { wch: 24 }, { wch: 30 },\n          { wch: 16 }, { wch: 14 }, { wch: 12 }, { wch: 10 }, { wch: 24 }\n        ];\n        const wb = XLSX.utils.book_new();\n        XLSX.utils.book_append_sheet(wb, ws, 'Registrations');\n        XLSX.writeFile(wb, `AWS_Community_Day_Registrations_${new Date().toISOString().slice(0, 10)}.xlsx`);\n        showToast('Excel (.xlsx) downloaded successfully! 📊');\n      } else {\n        alert('Could not export to Excel. Please check connection.');\n      }\n    });\n\n    // CSV EXPORT\n    document.getElementById('exportCsvBtn').addEventListener('click', function() {\n      if (allRegistrations.length === 0) {\n        alert('No registrations available to export.');\n        return;\n      }\n\n      const headers = ['S.No', 'Pass ID', 'Full Name', 'Email', 'Mobile', 'Branch', 'Year', 'Section', 'Registered On'];\n      const rows = allRegistrations.map((item, idx) => [\n        idx + 1,\n        `\"${item.id}\"`,\n        `\"${(item.name || '').replace(/\"/g, '\"\"')}\"`,\n        `\"${(item.email || '').replace(/\"/g, '\"\"')}\"`,\n        `\"${item.phone}\"`,\n        `\"${item.branch}\"`,\n        `\"${item.year} Year\"`,\n        `\"${item.section}\"`,\n        `\"${item.formattedDate || item.registeredAt || ''}\"`\n      ]);\n\n      const csvContent = 'data:text/csv;charset=utf-8,' + \n        [headers.join(','), ...rows.map(e => e.join(','))].join('\\n');\n      \n      const encodedUri = encodeURI(csvContent);\n      const link = document.createElement('a');\n      link.setAttribute('href', encodedUri);\n      link.setAttribute('download', `AWS_Community_Day_Registrations_${new Date().toISOString().slice(0, 10)}.csv`);\n      document.body.appendChild(link);\n      link.click();\n      link.remove();\n      showToast('CSV downloaded successfully! 📄');\n    });\n\n    // Filters event listeners\n    searchInput.addEventListener('input', renderTable);\n    branchFilter.addEventListener('change', renderTable);\n    yearFilter.addEventListener('change', renderTable);\n    document.getElementById('refreshBtn').addEventListener('click', () => {\n      loadData();\n      showToast('Data refreshed! 🔄');\n    });\n\n    // Settings Modal\n    const openSettingsBtn = document.getElementById('openSettingsBtn');\n    const closeSettingsModal = document.getElementById('closeSettingsModal');\n    const cancelSettingsBtn = document.getElementById('cancelSettingsBtn');\n\n    openSettingsBtn.addEventListener('click', () => {\n      adminWhatsAppInput.value = settings.adminWhatsApp || '';\n      settingsModal.classList.add('active');\n    });\n\n    function hideSettingsModal() {\n      settingsModal.classList.remove('active');\n    }\n\n    closeSettingsModal.addEventListener('click', hideSettingsModal);\n    cancelSettingsBtn.addEventListener('click', hideSettingsModal);\n\n    settingsForm.addEventListener('submit', async (e) => {\n      e.preventDefault();\n      const num = adminWhatsAppInput.value.replace(/[^0-9]/g, '');\n      settings.adminWhatsApp = num;\n\n      try {\n        await fetch('/api/settings', {\n          method: 'POST',\n          headers: { 'Content-Type': 'application/json' },\n          body: JSON.stringify({ adminWhatsApp: num })\n        });\n      } catch (err) {\n        console.warn('Could not save to backend, stored locally:', err);\n      }\n\n      localStorage.setItem('aws_settings_cache', JSON.stringify(settings));\n      hideSettingsModal();\n      updateUI();\n      showToast('WhatsApp Settings Saved! 💬');\n    });\n\n    // Close on overlay click\n    window.addEventListener('click', (e) => {\n      if (e.target === settingsModal) hideSettingsModal();\n    });\n\n    // Check Authentication State\n    function checkAuth() {\n      const isAuth = sessionStorage.getItem('aws_admin_auth');\n      if (isAuth === 'true') {\n        loginView.style.display = 'none';\n        dashboardView.style.display = 'flex';\n        loadData();\n      } else {\n        loginView.style.display = 'flex';\n        dashboardView.style.display = 'none';\n      }\n    }\n\n    // Login Form Submit\n    adminLoginForm.addEventListener('submit', async function(e) {\n      e.preventDefault();\n      loginAlert.style.display = 'none';\n      loginSubmitBtn.disabled = true;\n      loginSubmitBtn.innerHTML = 'AUTHENTICATING... ⏳';\n\n      const u = loginUsername.value.trim();\n      const p = loginPassword.value.trim();\n\n      try {\n        const res = await fetch('/api/login', {\n          method: 'POST',\n          headers: { 'Content-Type': 'application/json' },\n          body: JSON.stringify({ username: u, password: p })\n        });\n\n        if (res.ok) {\n          sessionStorage.setItem('aws_admin_auth', 'true');\n          loginUsername.value = '';\n          loginPassword.value = '';\n          checkAuth();\n          showToast('Welcome back, Admin! 🚀');\n          return;\n        } else {\n          throw new Error('Invalid credentials');\n        }\n      } catch (err) {\n        // Fallback local check\n        if (u === 'admin' && p === 'admin123') {\n          sessionStorage.setItem('aws_admin_auth', 'true');\n          loginUsername.value = '';\n          loginPassword.value = '';\n          checkAuth();\n          showToast('Welcome back, Admin! 🚀');\n          return;\n        }\n\n        loginAlert.style.display = 'block';\n        loginAlert.textContent = '⚠️ Invalid username or password. Please try again.';\n      } finally {\n        loginSubmitBtn.disabled = false;\n        loginSubmitBtn.innerHTML = '⚡ SIGN IN TO DASHBOARD &rarr;';\n      }\n    });\n\n    // Logout Action\n    logoutBtn.addEventListener('click', function() {\n      sessionStorage.removeItem('aws_admin_auth');\n      showToast('Logged out successfully. 🔒');\n      checkAuth();\n    });\n\n    // Initialize View with Auth Check\n    checkAuth();\n  </script>\n</body>\n</html>\n"
};
